package com.braseiro.pathfinder2e;
import android.content.Context;
import org.json.JSONArray;
import org.json.JSONObject;
import java.security.MessageDigest;
import java.util.*;

/** Homologa exportação/importação em um banco sandbox e compara o conteúdo lógico da campanha. */
public final class BackupRoundTripVerifier {
    private BackupRoundTripVerifier(){}
    public static JSONObject verify(Context c,AppDb live){JSONObject report=new JSONObject();String temp="braseiro_roundtrip_6.db";AppDb sandbox=null;try{
        JSONObject before=live.exportAll();String world=live.getActiveMapProfile();c.deleteDatabase(temp);sandbox=new AppDb(c,temp);sandbox.setActiveMapProfile(world);sandbox.getWritableDatabase();sandbox.importAll(new JSONObject(before.toString()));JSONObject after=sandbox.exportAll();JSONObject a=fingerprint(before),b=fingerprint(after);boolean ok=a.optString("sha256").equals(b.optString("sha256"))&&a.optJSONObject("counts").toString().equals(b.optJSONObject("counts").toString());report.put("ok",ok).put("before",a).put("after",b).put("backup_version",before.optInt("version"));
    }catch(Exception e){try{report.put("ok",false).put("error",String.valueOf(e.getMessage()));}catch(Exception ignored){AppLog.ignored("BackupRoundTripVerifier","Falha tolerada registrada na consolidação 5.0.",ignored);}}finally{try{if(sandbox!=null)sandbox.close();}catch(Exception ignored){AppLog.ignored("BackupRoundTripVerifier","Falha tolerada registrada na consolidação 5.0.",ignored);}c.deleteDatabase(temp);}return report;}
    private static JSONObject fingerprint(JSONObject root)throws Exception{String[] keys={"characters","journal","combatants","npcMemories","npcCognitiveStates","knowledgeFacts","quests","factions","worldClocks","worldEvents","pendingTransactions","pendingActions","lifeActivities","livingTroupes","guilds","guildMembers","guildContracts","guildProjects","tacticalTokens","emergentArcs","settlementStates","worldHistoryEvents","rumors","rumorKnowledge","campaignLegacies","npcVoiceProfiles","tacticalScenes","localTableSecrets"};JSONObject counts=new JSONObject();StringBuilder material=new StringBuilder();material.append(root.optString("worldProfile")).append('|').append(stable(root.optJSONObject("campaign"))).append('|').append(stable(root.optJSONObject("storyState"))).append('|').append(stable(root.optJSONObject("sceneState"))).append('|').append(stable(root.optJSONObject("worldSeed")));for(String k:keys){JSONArray a=root.optJSONArray(k);int n=a==null?0:a.length();counts.put(k,n);material.append('|').append(k).append(':');ArrayList<String> rows=new ArrayList<String>();if(a!=null)for(int i=0;i<a.length();i++)rows.add(stable(a.opt(i)));Collections.sort(rows);for(String row:rows)material.append(row).append(';');}return new JSONObject().put("counts",counts).put("sha256",sha(material.toString()));}
    private static String stable(Object value)throws Exception{if(value==null||value==JSONObject.NULL)return "null";if(value instanceof JSONArray){JSONArray a=(JSONArray)value;ArrayList<String> rows=new ArrayList<String>();for(int i=0;i<a.length();i++)rows.add(stable(a.opt(i)));Collections.sort(rows);return rows.toString();}if(value instanceof JSONObject){JSONObject o=(JSONObject)value;ArrayList<String> keys=new ArrayList<String>();Iterator<String> it=o.keys();while(it.hasNext())keys.add(it.next());Collections.sort(keys);StringBuilder b=new StringBuilder("{");for(String k:keys){if(k.equals("id")||k.endsWith("_at")||k.equals("created_at")||k.equals("updated_at")||k.equals("exportedAt")||k.equals("appVersion"))continue;b.append(k).append('=').append(stable(o.opt(k))).append(';');}return b.append('}').toString();}return String.valueOf(value);}
    private static String sha(String s)throws Exception{byte[] d=MessageDigest.getInstance("SHA-256").digest(s.getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte x:d)b.append(String.format(Locale.ROOT,"%02x",x));return b.toString();}
}
